from collections import deque

class Node:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

class Checker:
    def _to_tree(self, root):
        if root is None or root == []:
            return None
        if hasattr(root, "val"):
            return root
        if not isinstance(root, list) or not root or root[0] is None:
            return None
        tree_root = Node(root[0])
        queue = [tree_root]
        i = 1
        while queue and i < len(root):
            node = queue.pop(0)
            if i < len(root) and root[i] is not None:
                node.left = Node(root[i])
                queue.append(node.left)
            i += 1
            if i < len(root) and root[i] is not None:
                node.right = Node(root[i])
                queue.append(node.right)
            i += 1
        return tree_root

    def rightSideView(self, root, result):
        if not isinstance(result, list):
            return False
        root = self._to_tree(root)
        if root is None:
            return result == []
        expected = []
        queue = deque([root])
        while queue:
            rightmost = None
            for _ in range(len(queue)):
                node = queue.popleft()
                rightmost = node.val
                if node.left is not None:
                    queue.append(node.left)
                if node.right is not None:
                    queue.append(node.right)
            expected.append(rightmost)
        return result == expected

